/**
 * Loads an issue that belongs to `orgId`. An id that exists in another
 * workspace is a tenant-scope violation; an id that does not exist is not found.
 */
async function requireWorkspaceIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (issue !== null) return issue;

  const foreign = await issueRepo.findIssueByIdAny(issueId);
  if (foreign !== null) assertOrgScope(actor, foreign.orgId);
  throw new NotFoundError("Issue", issueId);
}

/** Same rule as `requireWorkspaceIssue`, for the project an issue is filed under. */
async function requireWorkspaceProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (project !== null) return project;

  const foreign = await projectRepo.findProjectByIdAny(projectId);
  if (foreign !== null) assertOrgScope(actor, foreign.orgId);
  throw new NotFoundError("Project", projectId);
}

/**
 * A parent must be a live issue of the same project. Cross-workspace parents
 * are tenant-scope violations; anything else that is not usable is not found.
 */
async function assertParentIssue(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId | null,
): Promise<void> {
  if (parentId === null) return;

  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (parent === null) {
    const foreign = await issueRepo.findIssueByIdAny(parentId);
    if (foreign !== null) assertOrgScope(actor, foreign.orgId);
    throw new NotFoundError("Issue", parentId);
  }

  if (!isLive(parent) || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
}

/** Every label id must already belong to this workspace. */
async function assertWorkspaceLabels(
  actor: Actor,
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  if (labelIds.length === 0) return;

  const own = await labelRepo.listLabels(orgId);
  const ownIds = new Set(own.map((label) => label.id));

  for (const labelId of labelIds) {
    if (ownIds.has(labelId)) continue;
    const foreign = await labelRepo.findLabelById(labelId);
    if (foreign !== null) assertOrgScope(actor, foreign.orgId);
    throw new NotFoundError("Label", labelId);
  }
}

