/**
 * A current member is an active membership of this workspace. Removed,
 * invited, suspended, and unknown users are not found — a change that names
 * them is refused rather than attached to someone who cannot use it.
 */
export async function requireCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (member === null || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

