/**
 * A reply must target a live top-level comment on the same issue. A parent
 * that belongs to another workspace is a tenant-scope violation. A missing,
 * deleted, cross-issue, or nested parent is not found, and nothing is written.
 */
async function assertReplyTarget(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
  parentId: CommentId | null,
): Promise<void> {
  if (parentId === null) return;

  const parent = await commentRepo.findCommentById(orgId, parentId);
  if (parent === null) {
    const foreign = await commentRepo.findCommentByIdAny(parentId);
    if (foreign !== null) assertOrgScope(actor, foreign.orgId);
    throw new NotFoundError("Comment", parentId);
  }

  if (!isLive(parent) || parent.issueId !== issueId || parent.parentId !== null) {
    throw new NotFoundError("Comment", parentId);
  }
}

async function requireWorkspaceIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (issue !== null) return issue;

  const foreign = await issueRepo.findIssueByIdAny(issueId);
  if (foreign !== null) assertOrgScope(actor, foreign.orgId);
  throw new NotFoundError("Issue", issueId);
}

async function requireWorkspaceComment(
  actor: Actor,
  orgId: OrgId,
  commentId: CommentId,
): Promise<Comment> {
  const comment = await commentRepo.findCommentById(orgId, commentId);
  if (comment !== null) return comment;

  const foreign = await commentRepo.findCommentByIdAny(commentId);
  if (foreign !== null) assertOrgScope(actor, foreign.orgId);
  throw new NotFoundError("Comment", commentId);
}

/** Every active member, past the first page, so a handle is never missed. */
async function listActiveMembers(orgId: OrgId): Promise<readonly MemberWithUser[]> {
  const collected: MemberWithUser[] = [];
  const seenCursors = new Set<string>();
  let cursor: string | null = null;

  for (;;) {
    const page = await memberRepo.listMembers({
      orgId,
      status: "active",
      limit: MENTION_LOOKUP_LIMIT,
      cursor,
    });
    collected.push(...page.items);
    if (page.nextCursor === null || seenCursors.has(page.nextCursor)) {
      return collected;
    }
    seenCursors.add(page.nextCursor);
    cursor = page.nextCursor;
  }
}

/**
 * Mentions are the current members named by an `@handle` or by the composer's
 * id list. Anyone else is dropped — the comment is still stored, and they are
 * not notified.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await listActiveMembers(orgId);
  const activeIds = new Set(members.map((member) => member.userId));
  const mentioned: UserId[] = [];
  const seen = new Set<UserId>();

  for (const userId of [...resolveMentions(body, members), ...clientProvided]) {
    if (seen.has(userId) || !activeIds.has(userId)) continue;
    seen.add(userId);
    mentioned.push(userId);
  }

  return mentioned;
}

