import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { newId } from "@/lib/id";
import { TenantScopeError } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { NotFoundError } from "@/server/services/_support";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { LabelId, UserId } from "@/types/common";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let home: Tenant;
let other: Tenant;
let homeIssue: Issue;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  home = await createTenant("home");
  other = await createTenant("other");
  homeIssue = await issueService.createIssue(
    home.actors.member,
    issueInput(home.org.id, home.project.id, { title: "Home issue" }),
  );
});

afterAll(() => {
  cleanup();
});

async function eventCount(
  name: "issue.created" | "issue.assigned" | "issue.updated" | "comment.created" | "project.created",
  run: () => Promise<unknown>,
): Promise<number> {
  let count = 0;
  const off = subscribe(name, () => {
    count += 1;
  });
  try {
    await run();
  } catch (error) {
    off();
    throw error;
  }
  off();
  return count;
}

describe("reference guards", () => {
  it("refuses a parent from another workspace and writes nothing", async () => {
    const foreign = await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "Foreign parent" }),
    );
    const before = await issueRepo.countIssues(home.org.id, home.project.id);

    await expect(
      eventCount("issue.created", () =>
        issueService.createIssue(home.actors.member, {
          ...issueInput(home.org.id, home.project.id, { title: "Bad child" }),
          parentId: foreign.id,
        }),
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);

    expect(await issueRepo.countIssues(home.org.id, home.project.id)).toBe(before);
  });

  it("refuses a parent from another project or an archived parent as not found", async () => {
    const second = await projectService.createProject(home.actors.admin, {
      orgId: home.org.id,
      name: "Second",
      slug: "second",
      key: "SEC",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const elsewhere = await issueService.createIssue(
      home.actors.member,
      issueInput(home.org.id, second.id, { title: "Other project" }),
    );
    const archived = await issueService.createIssue(
      home.actors.member,
      issueInput(home.org.id, home.project.id, { title: "Will archive" }),
    );
    await issueService.archiveIssue(home.actors.member, home.org.id, archived.id);

    const before = await issueRepo.countIssues(home.org.id, home.project.id, {
      includeArchived: true,
    });

    await expect(
      issueService.createIssue(home.actors.member, {
        ...issueInput(home.org.id, home.project.id, { title: "Wrong project parent" }),
        parentId: elsewhere.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.createIssue(home.actors.member, {
        ...issueInput(home.org.id, home.project.id, { title: "Archived parent" }),
        parentId: archived.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    expect(
      await issueRepo.countIssues(home.org.id, home.project.id, { includeArchived: true }),
    ).toBe(before);
  });

  it("accepts a live parent in the same project", async () => {
    const created = await issueService.createIssue(home.actors.member, {
      ...issueInput(home.org.id, home.project.id, { title: "Child" }),
      parentId: homeIssue.id,
    });
    expect(created.parentId).toBe(homeIssue.id);
  });

  it("refuses foreign and missing labels without changing the issue", async () => {
    const foreignLabel = await labelRepo.insertLabel({
      orgId: other.org.id,
      name: "Other customer",
      color: "#111111",
      description: null,
    });
    const ownLabel = await labelRepo.insertLabel({
      orgId: home.org.id,
      name: "Ours",
      color: "#222222",
      description: null,
    });
    const before = await issueRepo.findIssueById(home.org.id, homeIssue.id);

    await expect(
      eventCount("issue.updated", () =>
        issueService.updateIssue(home.actors.member, {
          orgId: home.org.id,
          issueId: homeIssue.id,
          title: "Should not stick",
          labelIds: [foreignLabel.id],
        }),
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      issueService.createIssue(home.actors.member, {
        ...issueInput(home.org.id, home.project.id, { title: "Missing label" }),
        labelIds: [newId() as LabelId],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const after = await issueRepo.findIssueById(home.org.id, homeIssue.id);
    expect(after?.title).toBe(before?.title);
    expect(after?.labelIds).toEqual([]);

    const created = await issueService.createIssue(home.actors.member, {
      ...issueInput(home.org.id, home.project.id, { title: "Labeled" }),
      labelIds: [ownLabel.id],
    });
    expect(created.labelIds).toEqual([ownLabel.id]);
  });

  it("hides a label from another workspace that was already attached", async () => {
    const foreignLabel = await labelRepo.insertLabel({
      orgId: other.org.id,
      name: "Smuggled",
      color: "#333333",
      description: null,
    });
    const number = await issueRepo.nextIssueNumber(home.org.id, home.project.id);
    const tainted = await issueRepo.insertIssue(
      {
        ...issueInput(home.org.id, home.project.id, { title: "Tainted" }),
        labelIds: [foreignLabel.id],
      },
      home.userIds.member,
      number,
    );

    const loaded = await issueService.getIssue(home.actors.member, home.org.id, tainted.id);
    expect(loaded.labels.map((label) => label.id)).not.toContain(foreignLabel.id);
    expect(loaded.issue.labelIds).not.toContain(foreignLabel.id);
  });

  it("refuses a stranger assignee or project lead and does not announce it", async () => {
    await expect(
      eventCount("issue.assigned", () =>
        issueService.assignIssue(home.actors.member, {
          orgId: home.org.id,
          issueId: homeIssue.id,
          assigneeId: other.userIds.owner,
        }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    const issue = await issueRepo.findIssueById(home.org.id, homeIssue.id);
    expect(issue?.assigneeId).toBeNull();

    const projectsBefore = await projectRepo.countProjects(home.org.id);
    await expect(
      eventCount("project.created", () =>
        projectService.createProject(home.actors.admin, {
          orgId: home.org.id,
          name: "Stranger lead",
          slug: "stranger-lead",
          key: "STR",
          description: null,
          visibility: "org",
          leadId: other.userIds.member,
          color: "#6366f1",
          targetDate: null,
        }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(await projectRepo.countProjects(home.org.id)).toBe(projectsBefore);
  });

  it("refuses replies that are not a live top-level comment on the same issue", async () => {
    const otherIssue = await issueService.createIssue(
      home.actors.member,
      issueInput(home.org.id, home.project.id, { title: "Other issue" }),
    );
    const top = await commentService.createComment(home.actors.member, {
      orgId: home.org.id,
      issueId: homeIssue.id,
      body: "top",
      parentId: null,
      mentionedUserIds: [],
    });
    const nested = await commentService.createComment(home.actors.member, {
      orgId: home.org.id,
      issueId: homeIssue.id,
      body: "nested",
      parentId: top.id,
      mentionedUserIds: [],
    });
    const elsewhere = await commentService.createComment(home.actors.member, {
      orgId: home.org.id,
      issueId: otherIssue.id,
      body: "elsewhere",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.deleteComment(home.actors.member, {
      orgId: home.org.id,
      commentId: top.id,
    });

    const foreignTop = await commentService.createComment(other.actors.member, {
      orgId: other.org.id,
      issueId: (
        await issueService.createIssue(
          other.actors.member,
          issueInput(other.org.id, other.project.id, { title: "Foreign thread" }),
        )
      ).id,
      body: "foreign top",
      parentId: null,
      mentionedUserIds: [],
    });

    const before = await commentRepo.countComments(home.org.id, homeIssue.id);

    await expect(
      commentService.createComment(home.actors.member, {
        orgId: home.org.id,
        issueId: homeIssue.id,
        body: "reply to other issue",
        parentId: elsewhere.id,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      commentService.createComment(home.actors.member, {
        orgId: home.org.id,
        issueId: homeIssue.id,
        body: "reply to deleted",
        parentId: top.id,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      commentService.createComment(home.actors.member, {
        orgId: home.org.id,
        issueId: homeIssue.id,
        body: "reply to reply",
        parentId: nested.id,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      commentService.createComment(home.actors.member, {
        orgId: home.org.id,
        issueId: homeIssue.id,
        body: "reply across workspace",
        parentId: foreignTop.id,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    expect(await commentRepo.countComments(home.org.id, homeIssue.id)).toBe(before);
  });

  it("ignores mentions of people who are not current members", async () => {
    const departed = await memberRepo.findMember(home.org.id, home.userIds.viewer);
    expect(departed).not.toBeNull();
    await memberService.removeMember(home.actors.owner, {
      orgId: home.org.id,
      memberId: departed!.id,
    });

    const received: { mentionedUserIds: readonly UserId[] }[] = [];
    const off = subscribe("comment.created", (payload) => {
      received.push(payload);
    });

    try {
      const comment = await commentService.createComment(home.actors.member, {
        orgId: home.org.id,
        issueId: homeIssue.id,
        body: "ping @admin and @viewer",
        parentId: null,
        mentionedUserIds: [other.userIds.owner, home.userIds.viewer, home.userIds.admin],
      });

      expect(comment.mentionedUserIds).toEqual([home.userIds.admin]);
      expect(received[0]?.mentionedUserIds).toEqual([home.userIds.admin]);
    } finally {
      off();
    }

    const strangerNotes = await notificationRepo.listNotifications({
      orgId: home.org.id,
      recipientId: other.userIds.owner,
      unreadOnly: false,
      limit: 20,
      cursor: null,
    });
    expect(strangerNotes.items).toEqual([]);

    const departedNotes = await notificationRepo.listNotifications({
      orgId: home.org.id,
      recipientId: home.userIds.viewer,
      unreadOnly: false,
      limit: 20,
      cursor: null,
    });
    expect(departedNotes.items.filter((note) => note.kind === "comment_mention")).toEqual([]);
  });
});

