async function eventCount(
  name: "issue.created" | "issue.assigned" | "issue.updated" | "comment.created" | "project.created",
  run: () => Promise<unknown>,
): Promise<number> {
  let count = 0;
  const off = subscribe(name, () => {
    count += 1;
  });
  try {
    await run();
  } catch (error) {
    off();
    throw error;
  }
  off();
  return count;
}

